import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n + 1)]
    idx = 1

    for i in range(1, n + 1):
        m = data[idx]
        idx += 1
        for _ in range(m):
            adj[i].append(data[idx])
            idx += 1

    color = [-1] * (n + 1)
    color[1] = 0
    q = deque([1])

    while q:
        u = q.popleft()
        for v in adj[u]:
            if color[v] == -1:
                color[v] = color[u] ^ 1
                q.append(v)

    for i in range(2, n + 1):
        if color[i] == -1:
            color[i] = 0
            q.append(i)
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        q.append(v)

    team1 = []
    team2 = []
    for i in range(1, n + 1):
        if color[i] == 0:
            team1.append(str(i))
        else:
            team2.append(str(i))

    sys.stdout.write(' '.join(team1) + '\n' + ' '.join(team2) + '\n')

